stress-test: Is this refresh-token rotation secure?

```ts
export async function refresh(req, res) {
  const token = req.cookies.rt;
  const row = await db.tokens.find(token);
  if (!row) return res.status(401).end();
  await db.tokens.delete(token);
  const next = crypto.randomUUID();
  await db.tokens.insert({ token: next, userId: row.userId });
  res.cookie('rt', next, { httpOnly: true });
  res.json({ access: sign(row.userId) });
}
```
